void mainImage(out vec4 FragColor, in vec2 fragCoord) {
    // Получаем разрешение текстуры
    vec2 resolution = iResolution.xy; // Используем iResolution, переданное из приложения

    // Получаем нормализованные координаты фрагмента
    vec2 uv = fragCoord / resolution;

    // Определяем количество сегментов по горизонтали и вертикали
    int segmentsX = 10; // 10 сегментов по X
    int segmentsY = 10; // 10 сегментов по Y
    int totalSegments = segmentsX * segmentsY;

    // Размер каждого сегмента
    vec2 segmentSize = vec2(1.0 / float(segmentsX), 1.0 / float(segmentsY));

    // Определяем текущий сегмент
    int segmentX = int(uv.x / segmentSize.x);
    int segmentY = int(uv.y / segmentSize.y);

    // Вычисляем индекс сегмента
    int segmentIndex = segmentY * segmentsX + segmentX;

    // Генерируем случайный индекс для перемешивания
    int randomIndex = int(mod(float(segmentIndex) * 3.14, float(totalSegments)));

    // Вычисляем координаты для случайного сегмента
    int randomSegmentX = randomIndex % segmentsX;
    int randomSegmentY = randomIndex / segmentsX;

    // Вычисляем UV координаты для случайного сегмента
    vec2 randomSegmentUV = vec2(float(randomSegmentX) * segmentSize.x, float(randomSegmentY) * segmentSize.y);

    // Получаем цвет из входного изображения через ichannel0
    vec4 color = texture(iChannel0, randomSegmentUV + vec2(0.0, segmentSize.y));

    // Устанавливаем цвет фрагмента
    FragColor = color; // Используем выходной параметр FragColor
}
